ProjectALife.DialogueShards["scenes_misc_11"] = {
{"s13_wire_school_bus_006","wire",3,"reg=military|mood=fear|world=vehicle",{1,"There's a school bus at the wire, county bus, yellow, full up",2,"Who's driving?",1,"A woman in a church dress, thirty in there, maybe, and half of 'em are kids",3,"Orders say nothing crosses",2,"Orders say nothing crosses, nobody wrote down what to do about a bus"}},
{"s13_wire_bus_decision_007","wire",3,"reg=military|role=soldier_nco|world=vehicle,road",{1,"Sergeant, what do we do?",2,"Take the bus off the road, park it in the church lot on our side, in the shade",3,"That's letting 'em through",2,"That's parking a bus - say it that way when they ask, and somebody will ask"}},
{"s13_wire_warning_over_010","wire",2,"reg=military|tmp=veteran|world=vehicle",{1,"Warning shots go over, over, into the field, where they can see the dirt jump",2,"And if they keep coming?",1,"Then the engine block, and you pray the driver's got sense enough to stop"}},
{"s13_wire_challenge_pass_011","wire",3,"reg=military|role=soldier_nco,soldier_green",{1,"Challenge is Dixie - password's Anchor",2,"Dixie - anchor - got it",1,"Running password's Buckeye, you hear Buckeye, that's ours coming in with no time to talk",3,"What if I forget it?",1,"Then you holler halt three times and you don't shoot till the fourth - say that back"}},
{"s13_wire_mother_at_wire_016","wire",3,"reg=military|mood=sad",{1,"Woman's been standing at the wire since noon, won't sit, won't take water",2,"What's she want?",1,"Her boy's on the other side at his grandmother's, he's nine years old",3,"We can't",1,"I know we can't, I'm telling you she is still standing there"}},
{"s13_wire_water_through_017","wire",2,"reg=military|mood=warm|world=road",{1,"You gave her water",2,"Set a canteen down on the road and walked back - that ain't opening the wire",1,"No it ain't - don't do it again where the lieutenant can see you",2,"Copy, Sergeant"}},
{"s13_wire_concertina_030","wire",2,"reg=military|tmp=veteran|world=building",{1,"Triple standard, stakes every five paces, and it still ain't a wall",2,"It ain't supposed to be a wall",1,"I know what it's for, it slows a man down long enough for you to decide",1,"I'd just like somebody with rank to say that part out loud one time"}},
{"s13_wire_bullhorn_039","wire",1,"reg=military|role=soldier_nco|world=road",{1,"I've got the bullhorn and I say the same five sentences all day long",1,"Road's closed - turn around, water's at the church - do not approach the wire",1,"Fifth one's mine, we will not shoot people who turn around, that ain't on the card and I'll answer for it"}},
{"s13_wire_flare_dark_044","wire",2,"reg=military|mood=fear",{1,"One flare left at post three",2,"Save it for a person, not for them",1,"How do I tell the difference in the dark?",2,"A person stops when you holler, every single time - that's how"}},
{"s13_wire_bring_them_water_048","wire",3,"reg=military|mood=warm",{1,"Lieutenant says set up water and shade on the far side of the wire",2,"That's the first good order all week",3,"It's also going to pull a crowd",1,"It is, he knows it - he said he'd rather have a crowd he can see"}},
{"s13_wire_farm_family_053","wire",3,"reg=military|role=soldier_nco",{1,"Farmer wants to cross and feed his cattle, forty head on the far side",2,"Orders",1,"He ain't leaving, he'll stand there till the cows are dead and then stand there some more",3,"Escort him, two men, one hour, and my name goes on it"}},
{"s13_wire_night_shift_054","wire",2,"reg=military|hour=21,4",{1,"Fifty percent security tonight, one up, one down, two hour shifts",2,"Nobody sleeps in two hours",1,"Nobody's sleeping anyway, at least this way it's official"}},
{"s13_wire_apology_057","wire",2,"reg=military|mood=sad|world=road",{1,"I told a man I was sorry today and he spit on the road",2,"He's allowed",1,"I know he is, I'd have spit too"}},
{"exp_worker_bubble","work_humor",2,"reg=worker|st=friendly,neutral,careful",{1,"New kid asked me where we kept the spare bubbles - for the level",2,"Aw, no - how long'd you let him look?",1,"Wasn't me! Foreman sent him - Kid'd been at it an hour",2,"An HOUR? Poor little bastard"}},
{"exp_worker_chairheight","work_humor",2,"reg=worker|st=friendly,neutral,careful",{1,"Boss had this big fancy chair, had to be taller than ours",2,"Oh, one of those guys",1,"His feet just dangled, couldn't touch the floor",2,"Stop, I'm picturing it and I can't--",2,"Did he swing his little feet when he fired people?"}},
{"exp_worker_fixed_twice","work_memory",2,"reg=worker|st=friendly,neutral,careful",{1,"Used to fix that pump every Friday, same seal, every damn Friday",2,"Nobody wanted to buy the right one?",1,"You know how it is - keep it running, we'll order it Monday",2,"Yeah, then Monday they'd act like they never said it"}},
{"ordinary_coffee_shift","work_memory",2,"reg=law|st=neutral,careful",{1,"I miss bad coffee in a paper cup",2,"You complained about that coffee every shift",1,"Had to have something to complain about",2,"We've certainly expanded the selection"}},
{"ordinary_mechanic_hands","work_memory",2,"reg=worker,club|st=neutral,friendly",{1,"Used to know what kind of day I'd had by the grease under my nails",2,"What do they tell you now?",1,"Mostly that I ought to wash my hands",2,"Some expertise carries over"}},
{"ordinary_calculator","work_memory",2,"reg=worker,civilian|st=neutral,friendly",{1,"Had a desk job, worst thing on it was a calculator that stuck",2,"Sounds unbearable",1,"I was very brave about it",2,"They should've given you a medal"}},
{"ordinary_guard_weekend","work_memory",2,"reg=military|tmp=fresh|st=neutral,careful",{1,"I was meant to be helping my brother move this weekend",2,"You got the better excuse",1,"I'd rather be carrying his damn sofa",2,"Yeah, I'd help with the other end"}},
